import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Updating","description":"","frontmatter":{"title":"Updating"},"headers":[],"relativePath":"en/guide/mise-a-jour.md","filePath":"en/guide/mise-a-jour.md"}'),o={name:"en/guide/mise-a-jour.md"};function s(r,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Daimon checks for a new version at launch, when its panel opens, and once a day, and shows the result in the panel.</p><ul><li><strong>Nothing is installed</strong> until you click <strong>Mettre à jour vers la v…</strong> (Update to v…).</li><li>The signature of each update is verified before it replaces the application.</li><li>During installation, the panel says so; if a check or an installation fails, it shows the reason.</li></ul><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>The <strong>Mettre à jour</strong> (Update) button installs the new version. You can also download it from the <a href="https://github.com/ArboRithm/Daimon/releases/latest" target="_blank" rel="noreferrer">releases page</a>.</p><h2 id="adjusting-or-turning-off-the-check" tabindex="-1">Adjusting or turning off the check <a class="header-anchor" href="#adjusting-or-turning-off-the-check" aria-label="Permalink to &quot;Adjusting or turning off the check&quot;">​</a></h2><p>Create an <code>update.yaml</code> file in the configuration folder (panel › <strong>Ouvrir le dossier de configuration</strong> (Open the configuration folder)). The keys read by the code, under <code>update:</code>, and their default values:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Automatic check</td></tr><tr><td><code>interval_hours</code></td><td><code>24</code></td><td>Interval between two checks, in hours</td></tr><tr><td><code>auto_apply</code></td><td><code>false</code></td><td>Apply automatically</td></tr><tr><td><code>allow_prerelease</code></td><td><code>false</code></td><td>Accept preview releases</td></tr><tr><td><code>channel</code></td><td>empty</td><td>Update channel; empty = the installed version&#39;s channel</td></tr></tbody></table><p>To turn off the automatic check:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>The check is Daimon&#39;s only Internet connection; it is served by GitHub Releases. See <a href="./confidentialite.html">Privacy</a>.</p>`,13)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
